import Foundation
import Testing
@testable import PixlLibrary

/// The stage 4 milestone 2 golden vectors: the chips under a mix card and their words (`assistantcards`), set notes (`setnotes`), the
/// weekly note (`weeklynote`) and the checks on the optional batch jobs (`assistbatch`). Generated by the Android repo's
/// `./gradlew :brain:generateGolden`, copied here unchanged. The README beside the files says how each `fn` is replayed.
@Suite("Brain stage 4 milestone 2 golden vectors (brainMatchesAndroid)")
struct BrainStage4M2GoldenTests {
    typealias G = BrainGoldenTests
    typealias S4 = BrainStage4GoldenTests

    static func evidence(_ i: BrainJson.Value) -> WeeklyNote.Evidence {
        WeeklyNote.Evidence(tracks: Int(G.int(i, "tracks")), newSongs: Int(G.int(i, "newSongs")), artists: S4.strings(i, "artists"),
                            genre: G.string(i, "genre"), island: G.string(i, "island"), newSharePct: Int(G.int(i, "newSharePct")))
    }

    // MARK: assistantcards.jsonl

    @Test func assistantCardsMatchAndroid() throws {
        var report = G.Report(file: "assistantcards.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("assistantcards.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "allChips":
                let q = AssistantRules.Query(
                    title: G.string(i, "title"), seedRefs: S4.strings(i, "seedRefs"), genreIds: S4.ints(i, "genreIds"), moodIds: [],
                    yearFrom: 0, yearTo: 0, energy: G.string(i, "energy"), tempo: G.string(i, "tempo"), novelty: G.string(i, "novelty"),
                    noveltySharePct: Int(G.int(i, "share")), count: Int(G.int(i, "count")),
                    excludeArtistRefs: S4.strings(i, "excludeArtistRefs"))
                let chips = AssistantCards.allChips(q, topArtistRef: G.string(i, "topArtistRef"), topGenreId: Int(G.int(i, "topGenreId")),
                                                    unsupported: S4.strings(i, "unsupported"))
                report.record(c, c.matches { S4.writeChips(&$0, "chips", chips) })
            case "chipLabel":
                let chip = AssistantRules.Chip(kind: Int(G.int(i, "kind")), ref: "yt:aaaaaaaaaaa", genreId: 5)
                let label = AssistantCards.chipLabel(chip, artistName: G.string(i, "artist"), genreName: G.string(i, "genre"))
                report.record(c, c.matches { $0.string("label", label) })
            case "lessTarget":
                let named = G.array(i, "named").map { v -> AssistantCards.Named in
                    let a = v.arrayValue ?? []
                    return AssistantCards.Named(kind: Int(a[0].bareLong ?? 0), name: a[1].stringValue ?? "")
                }
                let t = AssistantCards.lessTarget(userText: G.string(i, "user"), named: named)
                report.record(c, c.matches {
                    if let t { $0.string("target", t.name) } else { $0.nullValue("target") }
                    $0.string("label", t.map { AssistantCards.lessLabel($0.name) } ?? "")
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 140)
        #expect(counts["allChips"] == 40)
        #expect(counts["chipLabel"] == 96)
        #expect(counts["lessTarget"] == 9)
    }

    // MARK: setnotes.jsonl

    @Test func setNotesMatchAndroid() throws {
        var report = G.Report(file: "setnotes.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("setnotes.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "notes":
                let slots = G.array(i, "slots").map { v -> SetNotes.Slot in
                    let a = v.arrayValue ?? []
                    return SetNotes.Slot(artist: a[0].stringValue ?? "", genre: a[1].stringValue ?? "", known: (a[2].bareLong ?? 0) == 1)
                }
                let notes = SetNotes.notes(slots)
                report.record(c, c.matches {
                    $0.beginArray("notes")
                    for x in notes {
                        $0.beginArray(); $0.intItem(x.index); $0.intItem(x.kind); $0.intItem(x.count); $0.stringItem(x.genre)
                        $0.stringItem(x.artist); $0.stringItem(x.newArtist); $0.stringItem(SetNotes.text(x)); $0.endArray()
                    }
                    $0.endArray()
                })
            case "firstGenre":
                let g = SetNotes.firstGenre(G.string(i, "raw"))
                report.record(c, c.matches { $0.string("genre", g) })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 60)
        #expect(counts["notes"] == 60)
        #expect(counts["firstGenre"] == 7)
    }

    // MARK: weeklynote.jsonl

    @Test func weeklyNoteMatchesAndroid() throws {
        var report = G.Report(file: "weeklynote.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("weeklynote.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            let e = Self.evidence(i)
            switch c.fn {
            case "template":
                report.record(c, c.matches {
                    $0.string("text", WeeklyNote.template(e)); $0.string("lines", WeeklyNote.evidenceLines(e))
                    $0.long("hash", WeeklyNote.evidenceHash(e))
                })
            case "check":
                let cloud = G.string(i, "cloud")
                let r = WeeklyNote.check(cloud, e)
                report.record(c, c.matches {
                    if let r { $0.string("text", r) } else { $0.nullValue("text") }
                    $0.int("sentences", WeeklyNote.sentenceCount(WeeklyNote.oneLine(cloud)))
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 16)
        #expect(counts["template"] == 6)
        #expect(counts["check"] == 11)
    }

    // MARK: assistbatch.jsonl

    @Test func assistantBatchChecksMatchAndroid() throws {
        var report = G.Report(file: "assistbatch.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("assistbatch.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "cacheKey":
                let k = AssistBatch.cacheKey(modelId: G.string(i, "model"), kind: G.string(i, "kind"), input: G.string(i, "input"))
                report.record(c, c.matches { $0.long("key", k) })
            case "islandNames":
                func split(_ s: String) -> [String] { s.isEmpty ? [] : s.components(separatedBy: "|") }
                let ins = G.array(i, "ins").map { v -> AssistBatch.IslandIn in
                    let a = v.arrayValue ?? []
                    return AssistBatch.IslandIn(id: Int(a[0].bareLong ?? 0), genres: split(a[1].stringValue ?? ""), artists: split(a[2].stringValue ?? ""))
                }
                let outs = G.array(i, "outs").map { v -> AssistBatch.IslandName in
                    let a = v.arrayValue ?? []
                    return AssistBatch.IslandName(id: Int(a[0].bareLong ?? 0), name: a[1].stringValue ?? "", line: a[2].stringValue ?? "")
                }
                let kept = AssistBatch.validateIslandNames(ins, outs)
                report.record(c, c.matches {
                    $0.beginArray("kept")
                    for k in kept { $0.beginArray(); $0.intItem(k.id); $0.stringItem(k.name); $0.stringItem(k.line); $0.endArray() }
                    $0.endArray()
                })
            case "tags":
                let shortlists = G.array(i, "shortlists").map { v in (v.arrayValue ?? []).map { Int($0.bareLong ?? 0) } }
                let outs = G.array(i, "outs").map { v -> AssistBatch.TagOut in
                    let a = v.arrayValue ?? []
                    return AssistBatch.TagOut(index: Int(a[0].bareLong ?? 0), atlasId: Int(a[1].bareLong ?? 0), confidence: a[2].doubleValue ?? .nan)
                }
                let kept = AssistBatch.validateTags(shortlists, outs)
                report.record(c, c.matches {
                    $0.beginArray("kept")
                    for t in kept { $0.beginArray(); $0.intItem(t.index); $0.intItem(t.atlasId); $0.doubleItem(t.confidence); $0.endArray() }
                    $0.endArray()
                })
            case "artistNames":
                let kept = AssistBatch.validateArtistNames(S4.strings(i, "raw"), knownFolded: Set(S4.strings(i, "known")))
                report.record(c, c.matches { S4.writeStrings(&$0, "kept", kept) })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 7)
        #expect(counts["cacheKey"] == 4)
        #expect(counts["islandNames"] == 1)
        #expect(counts["tags"] == 1)
        #expect(counts["artistNames"] == 1)
    }

    @Test func milestone2FilesAreInTheManifest() throws {
        let manifest = String(decoding: try G.fixtureData("MANIFEST.sha256"), as: UTF8.self)
        for name in ["assistantcards.jsonl", "setnotes.jsonl", "weeklynote.jsonl", "assistbatch.jsonl"] {
            #expect(manifest.contains("  \(name)"), "\(name) is not in MANIFEST.sha256")
        }
    }
}
